def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(s: str) -> int | None:
        if s and s.isascii() and s.isdigit():
            return int(s)
        return None

    for idx, op in enumerate(ops):
        tokens = op.split(" ")
        verb = tokens[0]

        if verb == "open" and len(tokens) == 3:
            acc, amount = tokens[1], parse_amount(tokens[2])
            if amount is not None and acc not in balances:
                balances[acc] = amount
                history.append(("open", acc))
            else:
                rejected.append(idx)

        elif verb == "deposit" and len(tokens) == 3:
            acc, amount = tokens[1], parse_amount(tokens[2])
            if amount is not None and amount > 0 and acc in balances:
                balances[acc] += amount
                history.append(("deposit", acc, amount))
            else:
                rejected.append(idx)

        elif verb == "withdraw" and len(tokens) == 3:
            acc, amount = tokens[1], parse_amount(tokens[2])
            if (
                amount is not None
                and amount > 0
                and acc in balances
                and acc not in frozen
                and balances[acc] >= amount
            ):
                balances[acc] -= amount
                history.append(("withdraw", acc, amount))
            else:
                rejected.append(idx)

        elif verb == "transfer" and len(tokens) == 4:
            src, dst, amount = tokens[1], tokens[2], parse_amount(tokens[3])
            if (
                amount is not None
                and amount > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amount
            ):
                balances[src] -= amount
                balances[dst] += amount
                history.append(("transfer", src, dst, amount))
            else:
                rejected.append(idx)

        elif verb == "freeze" and len(tokens) == 2:
            acc = tokens[1]
            if acc in balances and acc not in frozen:
                frozen.add(acc)
                history.append(("freeze", acc))
            else:
                rejected.append(idx)

        elif verb == "unfreeze" and len(tokens) == 2:
            acc = tokens[1]
            if acc in balances and acc in frozen:
                frozen.remove(acc)
                history.append(("unfreeze", acc))
            else:
                rejected.append(idx)

        elif verb == "undo" and len(tokens) == 1:
            if not history:
                rejected.append(idx)
            else:
                entry = history.pop()
                kind = entry[0]
                if kind == "open":
                    del balances[entry[1]]
                elif kind == "deposit":
                    balances[entry[1]] -= entry[2]
                elif kind == "withdraw":
                    balances[entry[1]] += entry[2]
                elif kind == "transfer":
                    balances[entry[1]] += entry[3]
                    balances[entry[2]] -= entry[3]
                elif kind == "freeze":
                    frozen.remove(entry[1])
                elif kind == "unfreeze":
                    frozen.add(entry[1])

        else:
            rejected.append(idx)

    return balances, rejected
